/* InnerU classroom desk. Reading imported work never loads it into the learner. */
(() => {
  'use strict';
  const T=window.InneruTeacher,L=window.InneruLearning;
  const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const number=n=>new Intl.NumberFormat('en-AE').format(n||0);
  const date=v=>v&&Number.isFinite(Date.parse(v))?new Intl.DateTimeFormat('en-AE',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Dubai'}).format(new Date(v)):'Not shared';
  const arrow='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12h15m-6-6 6 6-6 6"/></svg>';
  const image=w=>'assets/home-expedition/'+w.image+'.webp';
  const routeFor=(id='',view='overview')=>'#teacher'+(id?'/student/'+encodeURIComponent(id):'')+(view==='overview'?'':'?view='+view);
  let rows=[],token=0,notice=null,search='',group='',filter='',sort='name',answerSystem='',answerStatus='',badgeSystem='',dirty=false;
  let schoolMode=false,schoolClasses=[],controls=null,controlClass='',controlError='',dashboardClass='',boardClass='',boardMetric='xp';
  async function classroomApi(action,values){
    if(window.InneruCloud)return InneruCloud.api(action,values);
    // This dashboard can load before the shared sync script on a fast session.
    const response=await fetch('/api/learning?action='+action,{method:values===undefined?'GET':'POST',credentials:'same-origin',cache:'no-store',headers:values===undefined?{}:{'Content-Type':'application/json'},...(values===undefined?{}:{body:JSON.stringify(values)})});
    let data;try{data=await response.json();}catch{throw new Error('Your assigned classroom could not be loaded. Please refresh to try again.');}
    if(!response.ok)throw new Error(data.error||'Your assigned classroom could not be loaded.');return data;
  }
  function cloudRecord(s){const payload=T.summary(s.snapshot||{name:s.name,done:[],rewards:[]});payload.n=s.name;payload.at=s.updatedAt;return {id:s.id,name:s.name,group:s.classCode||s.group||'',payload,importedAt:s.updatedAt,avatarId:s.avatarId,notes:'',feedback:s.feedback||{},cloud:true};}
  function locationState(){const [path,query='']=location.hash.slice(1).split('?');return {id:path.startsWith('teacher/student/')?decodeURIComponent(path.slice(16)):null,view:new URLSearchParams(query).get('view')||'overview'};}
  const meter=(value,label)=>`<div class="td-meter" role="progressbar" aria-label="${E(label)}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${value}"><i style="width:${value}%"></i></div>`;
  const tag=(text,kind='')=>`<span class="td-tag ${kind}">${E(text)}</span>`;
  const empty=(title,text,action='')=>`<div class="td-empty"><span class="td-empty-mark" aria-hidden="true">✧</span><h3>${title}</h3><p>${text}</p>${action}</div>`;
  const reviewed=(r,a)=>!!r.feedback?.[a.id]?.reviewedAt&&Date.parse(r.feedback[a.id].submissionAt)===Date.parse(a.at);
  function labelSystem(id){return L.worlds.find(w=>w.id===id)?.name||'Whole-body learning';}
  function stats(records){return {count:records.length,xp:records.reduce((n,r)=>n+r.model.xp,0),progress:records.length?Math.round(records.reduce((n,r)=>n+r.model.percent,0)/records.length):0,review:records.reduce((n,r)=>n+r.model.needsReview,0),achievements:records.reduce((n,r)=>n+r.model.earned.length,0)};}
  function classOptions(){return [...new Set([...schoolClasses,...rows.map(r=>r.group).filter(Boolean)])].sort();}
  function roster(){
    return rows.filter(r=>(!search||r.name.toLowerCase().includes(search.toLowerCase()))&&(!group||r.group===group)&&(!filter||filter==='review'&&r.model.needsReview||filter==='complete'&&r.model.percent===100||filter==='summary'&&r.model.summaryOnly)).sort((a,b)=>sort==='xp'?b.model.xp-a.model.xp:sort==='progress'?b.model.percent-a.model.percent:sort==='recent'?b.importedAt.localeCompare(a.importedAt):a.name.localeCompare(b.name));
  }
  function topline(student){return `<div class="td-topline"><span>INNERU / TEACHER WORKSPACE</span><div><span class="td-save-dot" aria-hidden="true"></span>${schoolMode?'Assigned school classes':'Browser classroom'} <button type="button" data-td-refresh>Refresh records ↻</button></div></div>${student?`<a class="td-back" href="${routeFor('','students')}">← All students</a>`:''}`;}
  function hero(student){
    const s=stats(student?[student]:rows);
    return `<section class="td-hero ${student?'td-hero-student':''}"><div class="td-hero-copy"><span class="td-kicker">${student?'INDIVIDUAL LEARNING RECORD':'YOUR CLASSROOM / A CLEARER PICTURE'}</span><h1 data-iu-private dir="auto">${student?E(student.name):'Every explorer.<br><em>Every discovery.</em>'}</h1><p>${student?'Follow the evidence behind this learner’s progress, responses and achievements.':'See who is progressing, understand their answers and celebrate what they have learned.'}</p><div class="td-hero-actions">${student?`<span class="td-hero-group">${E(student.group||'No class group')}</span><span>Snapshot shared ${date(student.payload.at)}</span>`:'<button type="button" class="td-button td-button-light" data-td-import>'+(schoolMode?'View assigned students ':'Collect student progress ')+arrow+'</button><span>'+(schoolMode?'Your classes · '+(schoolClasses.map(E).join(' · ')||'No school classes assigned yet'):'Student snapshots via progress codes')+'</span>'}</div></div>${student?`<div class="td-progress-ring" role="progressbar" aria-label="${E(student.name)} expedition progress" aria-valuenow="${student.model.percent}" aria-valuemin="0" aria-valuemax="100"><svg viewBox="0 0 180 180" aria-hidden="true"><circle cx="90" cy="90" r="74"/><circle cx="90" cy="90" r="74" style="stroke-dashoffset:${465*(1-student.model.percent/100)}"/></svg><strong>${student.model.percent}<small>%</small></strong><span>EXPEDITION EXPLORED</span></div>`:'<figure><img src="assets/login/teacher-guide-welcome.webp" alt="Welcoming educator guiding a classroom." width="1000" height="667"><figcaption>GUIDE CURIOSITY. NOTICE GROWTH.</figcaption></figure>'}</section><div class="td-metrics"><article><span class="td-kicker">${student?'MISSIONS COMPLETED':schoolMode?'STUDENTS ASSIGNED TO YOU':'STUDENTS IN YOUR REGISTER'}</span><strong data-td-students>${student?student.model.missions:number(s.count)}${student?'<small> / '+student.model.missionTotal+'</small>':''}</strong><p>${student?'Completed learning missions':schoolMode?schoolClasses.join(' · '):'Add a learner or import a progress code'}</p></article><article><span class="td-kicker">${student?'POINTS EARNED':'AVERAGE EXPEDITION PROGRESS'}</span><strong data-td-progress>${student?number(student.model.xp):s.progress}${student?'<small> XP</small>':'<small>%</small>'}</strong><p>${student?'Read from their actual learning record':s.count?'Across saved student snapshots':schoolMode?'Progress appears as your students learn':'Progress appears after the first import'}</p></article><article><span class="td-kicker">CONFIRMED ACHIEVEMENTS</span><strong data-td-earned>${number(s.achievements)}</strong><p>Earned through completed learning tasks</p></article><article class="td-review-stat"><span class="td-kicker">WORK TO REVIEW</span><strong data-td-review-count>${number(s.review)}</strong><p>Written responses and answers to revisit</p></article></div>`;
  }
  function navigation(id,view){const tabs=id?[['overview','Learning summary'],['progress','Mission progress'],['answers','Answers & feedback'],['achievements','Achievements'],['notes','Teacher notes']]:[['overview','Overview'],['students','Students'],['controls','Missions'],['answers','Feedback'],['analytics','Analytics']];return `<nav class="td-tabs" aria-label="${id?'Student learning record':'Teacher dashboard views'}">${tabs.map(([v,label])=>`<a href="${routeFor(id,v)}" aria-current="${v===view?'page':'false'}">${label}${v==='answers'&&stats(id?rows.filter(r=>r.id===id):rows).review?'<b>'+stats(id?rows.filter(r=>r.id===id):rows).review+'</b>':''}</a>`).join('')}</nav>`;}
  function alerts(student){return `${notice?`<p class="td-notice ${notice.error?'is-error':''}" role="${notice.error?'alert':'status'}">${E(notice.text)}</p>`:''}<p class="td-update" data-td-update hidden role="status">A newer class record is available. <button type="button" data-td-refresh>Refresh when you are ready</button></p>${student?.model.summaryOnly?'<p class="td-data-note">Summary-only progress code. Totals and mastery keys were shared; individual mission records and answers were not included. Import a current code to see detailed work.</p>':''}`;}
  function filters(){return `<form class="td-filterbar" data-td-roster-filter><label class="td-search">Find a student<input type="search" id="td-student-search" placeholder="Search by name" value="${E(search)}"></label><label>Class group<select id="td-group-filter"><option value="">All groups</option>${classOptions().map(c=>`<option ${group===c?'selected':''}>${E(c)}</option>`).join('')}</select></label><label>Show<select id="td-status-filter">${[['','All students'],['review','Work to review'],['complete','Expedition complete'],['summary','Summary-only records']].map(([v,t])=>`<option value="${v}" ${filter===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Sort by<select id="td-sort">${[['name','Student name'],['progress','Progress'],['xp','Earned XP'],['recent','Latest import']].map(([v,t])=>`<option value="${v}" ${sort===v?'selected':''}>${t}</option>`).join('')}</select></label></form>`;}
  function table(records){
    if(!records.length)return empty(rows.length?'No students match these filters.':'Your classroom starts with one explorer.',rows.length?'Change the name, group or review filters to see more learners.':schoolMode?'Students appear here after selecting one of your classes. Each record opens their synced learning.':'Add the learner on this device, or collect a progress code from another student. Each record opens a detailed learning view.','<button type="button" class="td-button" data-td-import>'+(schoolMode?'View assigned students ':'Collect student progress ')+arrow+'</button>');
    return `<div class="td-table-wrap"><table class="td-table"><caption class="sr-only">Students and their latest shared learning progress</caption><thead><tr><th scope="col">Student</th><th scope="col">Progress</th><th scope="col">Earned XP</th><th scope="col">Achievements</th><th scope="col">Review</th><th scope="col">Snapshot</th><th scope="col"><span class="sr-only">Open student</span></th></tr></thead><tbody>${records.map(r=>`<tr><th scope="row"><a class="td-student-link" href="${routeFor(r.id)}"><span class="td-avatar" aria-hidden="true">${E(r.name.charAt(0).toUpperCase())}</span><span><b>${E(r.name)}</b><small>${E(r.group||'No class group')}</small></span></a></th><td><b>${r.model.percent}%</b>${meter(r.model.percent,r.name+' expedition progress')}<small>${r.model.missions} / ${r.model.missionTotal} missions${r.model.summaryOnly?' · summary':''}</small></td><td><b>${number(r.model.xp)}</b></td><td>${r.model.earned.length}${r.model.summaryOnly?'<small>Confirmed only</small>':''}</td><td>${r.model.needsReview?`<a class="td-review-link" href="${routeFor(r.id,'answers')}">${r.model.needsReview} to review</a>`:tag(r.model.responses.length?'Up to date':'No answers shared','quiet')}</td><td><small>${date(r.payload.at||r.importedAt)}</small>${r.model.summaryOnly?tag('Summary only','quiet'):''}</td><td><a class="td-open-link" href="${routeFor(r.id)}" aria-label="Open ${E(r.name)}’s learning record">${arrow}</a></td></tr>`).join('')}</tbody></table></div>`;
  }
  function register(){return `<section class="td-section"><header class="td-section-heading"><div><span class="td-kicker">STUDENT REGISTER</span><h2>A learning story behind every name.</h2><p>Open a student to review their work, mission progress and earned achievements.</p></div><button type="button" class="td-button td-button-outline" data-td-export-csv>Export register CSV</button></header>${filters()}<div data-td-table>${table(roster())}</div><p class="td-footnote" data-td-roster-count>${roster().length} of ${rows.length} students shown. ${schoolMode?'Refresh records to load the latest synced progress.':'Snapshots update when a new code is imported.'}</p></section>`;}
  function learningPatterns(){
    const count=rows.length;
    return `<div class="td-overview-grid"><section class="td-section td-system-overview"><header class="td-section-heading"><div><span class="td-kicker">LEARNING ACROSS THE PLATFORM</span><h2>Notice where your class is growing.</h2><p>Average completion of missions and system finals in the saved snapshots.</p></div></header><div class="td-system-grid">${L.worlds.map(w=>{const average=count?Math.round(rows.reduce((n,r)=>n+r.model.worlds.find(s=>s.id===w.id).percent,0)/count):0;const keys=rows.filter(r=>r.model.worlds.find(s=>s.id===w.id).key).length;return `<button type="button" class="td-system-card" data-td-system="${w.id}"><img src="${image(w)}" width="440" height="294" alt=""><span>${w.name}</span><strong>${average}<small>%</small></strong>${meter(average,w.name+' class completion')}<small>${keys} / ${count} mastery keys confirmed</small></button>`;}).join('')}</div></section><aside class="td-section td-review-queue"><span class="td-kicker">YOUR NEXT CONVERSATIONS</span><h2>A little guidance goes a long way.</h2>${rows.some(r=>r.model.needsReview)?`<ol>${rows.filter(r=>r.model.needsReview).sort((a,b)=>b.model.needsReview-a.model.needsReview).slice(0,5).map(r=>`<li><a href="${routeFor(r.id,'answers')}"><span class="td-avatar">${E(r.name[0])}</span><span><b>${E(r.name)}</b><small>${r.model.needsReview} responses to review</small></span>${arrow}</a></li>`).join('')}</ol>`:`<div class="td-quiet-state"><span aria-hidden="true">✧</span><p>No submitted work is waiting for review.</p><small>${schoolMode?'New answers appear after your students sync their work.':'New answers appear when you import a student’s updated progress code.'}</small></div>`}<a class="td-text-link" href="${routeFor('','answers')}">Open the review desk ${arrow}</a></aside></div>`;
  }
  function progress(student){
    return `<section class="td-section"><header class="td-section-heading"><div><span class="td-kicker">MISSION-BY-MISSION EVIDENCE</span><h2>Follow the discoveries, system by system.</h2><p>Completed states come from the student’s learning record.</p></div></header><div class="td-world-records">${student.model.worlds.map(w=>`<article class="td-world-record"><header><img src="${image(w)}" alt="" width="440" height="294"><div><span class="td-kicker">${w.tag}</span><h3>${w.name} System</h3><p>${student.model.summaryOnly?w.reportedCount:w.done.length} / ${w.titles.length} missions complete · ${w.percent}%</p>${meter(w.percent,w.name+' progress')}</div>${tag(w.key?'Key earned':'In progress',w.key?'earned':'quiet')}</header>${student.model.summaryOnly?'<p class="td-data-note">This older code reports a total, without naming the completed missions.</p>':`<ol class="td-mission-list">${w.titles.map((title,i)=>`<li class="${w.done.includes(i+1)?'is-done':''}"><span aria-hidden="true">${w.done.includes(i+1)?'✓':String(i+1).padStart(2,'0')}</span><b>${E(title)}</b><small>${w.done.includes(i+1)?'Completed':'Not completed in this snapshot'}</small></li>`).join('')}</ol>`}<div class="td-world-final"><span>Final challenge · ${E(w.final)}</span>${tag(w.key?'Completed':'Not completed',w.key?'earned':'quiet')}</div></article>`).join('')}</div></section>`;
  }
  function studentSummary(r){
    const p=r.model;
    return `<div class="td-overview-grid"><section class="td-section"><header class="td-section-heading"><div><span class="td-kicker">PROGRESS AT A GLANCE</span><h2>${E(r.name)}’s discovery map.</h2></div><a class="td-text-link" href="${routeFor(r.id,'progress')}">View missions ${arrow}</a></header><div class="td-system-grid">${p.worlds.map(w=>`<a class="td-system-card" href="${routeFor(r.id,'progress')}"><img src="${image(w)}" alt="" width="440" height="294"><span>${w.name}</span><strong>${w.percent}<small>%</small></strong>${meter(w.percent,w.name+' progress')}<small>${w.key?'Mastery key earned':(p.summaryOnly?w.reportedCount:w.done.length)+' missions complete'}</small></a>`).join('')}</div></section><aside class="td-section td-student-evidence"><span class="td-kicker">ANSWER EVIDENCE</span><h2>Understanding, made visible.</h2><dl><div><dt>Submitted responses</dt><dd>${p.responses.length}</dd></div><div><dt>Latest graded responses correct</dt><dd>${p.accuracy===null?'—':p.accuracy+'%'}</dd></div><div><dt>Work awaiting review</dt><dd>${p.needsReview}</dd></div><div><dt>Last recorded activity</dt><dd class="td-date">${date(p.lastActivity)}</dd></div></dl><p class="td-footnote">Accuracy uses the latest recorded answer per automatically checked task. Written work is not included in this percentage.</p><a class="td-text-link" href="${routeFor(r.id,'answers')}">Review submitted work ${arrow}</a></aside></div><section class="td-section"><header class="td-section-heading"><div><span class="td-kicker">CONFIRMED ACHIEVEMENTS</span><h2>Celebrate the effort behind the badge.</h2></div><a class="td-text-link" href="${routeFor(r.id,'achievements')}">All achievements ${arrow}</a></header>${p.earned.length?`<div class="td-badge-grid">${p.earned.slice(0,6).map(b=>badge(b,r)).join('')}</div>`:empty('The first achievement is still ahead.','Badges appear after their required learning tasks are completed.')}</section>`;
  }
  function answerRows(student){return (student?[student]:rows).flatMap(r=>r.model.responses.map(a=>({student:r,answer:a}))).filter(({student:r,answer:a})=>(!answerSystem||a.system===answerSystem)&&(!answerStatus||answerStatus==='review'&&a.correct!==true&&!reviewed(r,a)||answerStatus==='correct'&&a.correct===true||answerStatus==='incorrect'&&a.correct===false||answerStatus==='written'&&a.correct===null)).sort((a,b)=>b.answer.at.localeCompare(a.answer.at));}
  function answerCards(student){
    const items=answerRows(student);
    if(!items.length)return empty('No matching answers to show.',(student?student.model.responses.length:rows.some(r=>r.model.responses.length))?'Change the system or answer filter to see other submissions.':schoolMode?'Students’ submitted answers appear after syncing. Earlier completed tasks do not contain a recoverable answer history.':'Import an updated progress code after students submit work. Earlier completed tasks do not contain a recoverable answer history.');
    return items.map(({student:r,answer:a})=>{const f=r.feedback?.[a.id]||{},done=reviewed(r,a);return `<article class="td-answer" data-iu-locale="${E(window.InneruLocale?.contextFor(a.system,a.id)||'')}" data-td-answer="${E(a.id)}"><header><div><a href="${routeFor(r.id)}">${E(r.name)}</a><span>${E(labelSystem(a.system))}${a.mission?' · Mission '+a.mission:''} · ${E(a.kind)}</span></div>${tag(a.correct===true?'Correct':a.correct===false?'Revisit the science':'Teacher review',a.correct===true?'earned':a.correct===false?'revisit':'pending')}</header><h3>${E(a.title||'Learning response')}</h3><p class="td-question">${E(a.prompt)}</p><div class="td-answer-columns"><div><span class="td-kicker">STUDENT’S ANSWER</span><p data-iu-private dir="auto">${E(a.answer||'No written answer')}</p></div>${a.expected?`<div><span class="td-kicker">REFERENCE / EXPECTED RESPONSE</span><p>${E(a.expected)}</p></div>`:''}</div>${a.feedback?`<p class="td-science-feedback">${E(a.feedback)}</p>`:''}<div class="td-answer-meta"><span>${date(a.at)} · ${a.attempts} recorded ${a.attempts===1?'attempt':'attempts'}</span>${tag(done?'Reviewed':'Not reviewed',done?'earned':'quiet')}</div>${a.history?.length?`<details class="td-history"><summary>See earlier attempts (${a.history.length} most recent)</summary><ol>${a.history.map(h=>`<li><span>${date(h.at)} · ${h.correct===true?'Correct':h.correct===false?'Incorrect':'Written response'}</span><p data-iu-private dir="auto">${E(h.answer)}</p></li>`).join('')}</ol></details>`:''}<details class="td-feedback" ${a.correct===null&&!done?'open':''}><summary>${f.note?'Teacher feedback saved':'Add feedback or mark reviewed'}</summary><form data-td-feedback data-student-id="${E(r.id)}" data-response-id="${E(a.id)}" data-response-at="${E(a.at)}"><label>Teacher feedback<textarea rows="3" maxlength="6000" placeholder="What did this learner understand? What should they try next?">${E(f.note||'')}</textarea></label><label class="td-check"><input type="checkbox" ${done?'checked':''}> I have reviewed this submission</label>${f.reviewedAt&&!done?'<p class="td-footnote">The earlier review applies to an older submission. Review this updated answer before marking it complete.</p>':''}<button type="submit" class="td-button td-button-small">Save feedback</button><p role="status" class="td-form-status"></p></form></details></article>`;}).join('');
  }
  function answers(student){return `<section class="td-section"><header class="td-section-heading"><div><span class="td-kicker">THE REVIEW DESK</span><h2>Read the answer. Understand the thinking.</h2><p>Written responses need teacher review. Completed tasks with no captured answer are never reconstructed.</p></div><button type="button" class="td-button td-button-outline" data-td-export-answers>Export responses CSV</button></header><div class="td-filterbar td-answer-filters"><label>Learning area<select id="td-answer-system"><option value="">All learning areas</option>${L.worlds.map(w=>`<option value="${w.id}" ${answerSystem===w.id?'selected':''}>${w.name}</option>`).join('')}<option value="extra" ${answerSystem==='extra'?'selected':''}>Whole-body learning</option></select></label><label>Response status<select id="td-answer-status">${[['','All responses'],['review','Awaiting teacher review'],['incorrect','Latest answer incorrect'],['correct','Latest answer correct'],['written','Written / ungraded work']].map(([v,t])=>`<option value="${v}" ${answerStatus===v?'selected':''}>${t}</option>`).join('')}</select></label><p data-td-answer-count>${answerRows(student).length} responses shown</p></div><div class="td-answer-list" data-td-answer-list>${answerCards(student)}</div><p class="td-footnote">Feedback is stored in your teacher register. Export or print it to share with students. Times are shown in UAE time.</p></section>`;}
  function badge(b,r,records=rows){
    const unknown=r?.model.summaryOnly&&b.kind==='mission';
    const count=r?Number(b.earned):records.filter(s=>s.model.badges.find(x=>x.id===b.id)?.earned).length;
    return `<button type="button" class="td-badge ${count?'is-earned':''} ${unknown?'is-unknown':''}" data-td-badge="${b.id}" ${r?'data-student-id="'+E(r.id)+'"':''}><span class="td-badge-mark" aria-hidden="true"><svg viewBox="0 0 64 64"><path d="M20 36 14 59l18-9 18 9-6-23"/><path d="m32 5 22 9v17c0 11-22 20-22 20S10 42 10 31V14Z"/><path d="m22 27 7 7 14-15"/></svg></span><span class="td-kicker">${E(labelSystem(b.system))}</span><strong>${E(b.name)}</strong><small>${unknown?'Mission detail not shared':r?b.earned?'✓ Earned':'Not earned yet':count+' / '+records.length+' students confirmed'}</small></button>`;
  }
  function achievements(student){const badges=(student?student.model.badges:L.snapshot().badges).filter(b=>!badgeSystem||b.system===badgeSystem);return `<section class="td-section"><header class="td-section-heading"><div><span class="td-kicker">THE ACHIEVEMENT CABINET</span><h2>${student?'Discoveries worth celebrating.':'See the discoveries your class has earned.'}</h2><p>Open a badge to see its exact requirement and the learners whose records confirm it.</p></div><label>Learning area<select id="td-badge-system"><option value="">All learning areas</option>${L.worlds.map(w=>`<option value="${w.id}" ${badgeSystem===w.id?'selected':''}>${w.name}</option>`).join('')}<option value="extra" ${badgeSystem==='extra'?'selected':''}>Whole-body learning</option></select></label></header><div class="td-badge-grid">${badges.map(b=>badge(b,student)).join('')}</div></section>`;}
  function notes(r){if(r.cloud)return `<section class="td-section"><span class="td-kicker">ASSIGNED CLASS / ${E(r.group)}</span><h2>Guidance, connected to the work.</h2><p>The school class determines this student’s teacher. Add feedback to individual submissions in Answers & feedback.</p><a class="td-text-link" href="${routeFor(r.id,'answers')}">Review answers ${arrow}</a></section>`;return `<section class="td-section td-notes"><span class="td-kicker">TEACHING NOTES / SAVED IN THIS BROWSER</span><h2>Make room for the whole learner.</h2><p>Keep class group and teaching notes alongside the student’s shared work. These notes do not alter their answers, XP or achievements.</p><form data-td-notes data-student-id="${E(r.id)}"><label for="td-class-group">Class group<input type="text" id="td-class-group" maxlength="60" placeholder="For example, Grade 10 A" value="${E(r.group)}"></label><label for="td-student-notes">Teaching notes<textarea id="td-student-notes" rows="7" maxlength="20000" placeholder="Strengths, helpful prompts, next steps…">${E(r.notes)}</textarea></label><button type="submit" class="td-button">Save teaching notes ${arrow}</button><p class="td-form-status" role="status"></p></form><div class="td-record-actions"><button type="button" class="td-button td-button-outline" data-td-print>Print this learning record</button><button type="button" class="td-danger" data-td-remove="${E(r.id)}">Remove from the teacher register</button></div></section>`;}
  function tools(){return `<section class="td-sharing" id="td-sharing"><header class="td-section-heading"><div><span class="td-kicker">COLLECT & PRESERVE LEARNING</span><h2>Bring each learner’s story into view.</h2><p>Import progress codes into the local classroom register. Signed-in, approved teachers can use the separate cloud classroom above for enrolled students’ synced work.</p></div></header><div class="td-share-grid"><section class="td-section"><span class="td-kicker">COLLECT STUDENT WORK</span><h3>Import a progress code.</h3><p>Updated codes carry recorded answers, mission progress and achievements. Older codes retain their available totals.</p><label for="t-import">Student progress code</label><textarea id="t-import" class="input" rows="3" placeholder="INNERU1-…" spellcheck="false"></textarea><div class="td-actions"><button type="button" class="td-button" id="t-add">Add / update student</button><button type="button" class="td-button td-button-outline" id="t-load">Restore learner on this device</button></div><p class="td-footnote">Restoring replaces this device’s learner profile and offers a 10-minute undo. Importing to the teacher register leaves it unchanged.</p><div id="t-import-out" role="status"></div></section><section class="td-section"><span class="td-kicker">LEARNER ON THIS DEVICE</span><h3>${E(state.name)} <small>· ${number(state.xp)} XP</small></h3><p>Add or update this learner’s snapshot in your register, or share their code with another teacher.</p><div class="td-actions"><button type="button" class="td-button" id="t-save">Add this learner to register</button><button type="button" class="td-button td-button-outline" id="t-code">Show progress code</button></div><div id="t-code-out"></div><div class="td-device-reset"><button type="button" class="td-text-link" id="t-reset">Finish for the next student</button><button type="button" class="td-text-link" id="t-undo" ${T.undoAvailable()?'':'hidden'}>Undo profile replacement</button></div><p class="td-footnote">Preparing a shared device clears only its active learner. Imported class records stay in your teacher register.</p></section></div><div class="td-backup-bar"><div><b>Your classroom, kept together.</b><p>Back up the register, answers and teacher feedback in one file.</p></div><div class="td-actions"><button type="button" class="td-button td-button-outline" data-td-backup>Export classroom backup</button><label class="td-file-button">Import backup<input type="file" data-td-backup-file accept="application/json,.json"></label><button type="button" class="td-text-link" id="t-print">Print dashboard</button><button type="button" class="td-danger" id="t-clear">Clear register</button></div></div></section>`;}
  const portrait=r=>window.InneruAccount.markup(r.avatarId,r.name);
  const selectedRows=code=>rows.filter(r=>!code||r.group===code);
  const classSelect=(id,value)=>`<label class="td-class-picker" for="${id}">Class<select id="${id}"><option value="">All assigned classes</option>${classOptions().map(c=>`<option value="${E(c)}" ${value===c?'selected':''}>${E(c)}</option>`).join('')}</select></label>`;
  function dashboardMetrics(records){const s=stats(records),missions=records.reduce((n,r)=>n+r.model.missions,0),correct=records.reduce((n,r)=>n+r.model.graded.filter(a=>a.correct).length,0);return `<div class="td-metrics td-workspace-metrics">${[
    ['world','Students',number(s.count),'data-td-students',dashboardClass||'Your assigned classes'],['book','Missions completed',number(missions),'', 'Across saved learning records'],['badge','Correct task responses',number(correct),'','Latest automatically checked answers'],['connect','Average progress',s.progress+'%','data-td-progress','Missions and system finals']
  ].map(([mark,title,value,attr,note])=>`<article><span class="td-metric-icon">${icon(mark)}</span><div><span class="td-kicker">${title}</span><strong ${attr}>${value}</strong><p>${E(note)}</p></div></article>`).join('')}</div>`;}
  function overviewBody(){
    const records=selectedRows(dashboardClass),recent=records.flatMap(r=>r.model.responses.map(a=>({r,a}))).sort((a,b)=>b.a.at.localeCompare(a.a.at)).slice(0,5),s=stats(records);
    return `${dashboardMetrics(records)}<div class="td-desk-grid"><section class="td-section"><header class="td-section-heading"><div><span class="td-kicker">RECENT ACTIVITY</span><h2>Latest submitted work</h2></div><a class="td-text-link" href="${routeFor('','answers')}">All feedback ${arrow}</a></header>${recent.length?`<ul class="td-activity-feed">${recent.map(({r,a})=>`<li><a href="${routeFor(r.id,'answers')}">${portrait(r)}<span><b>${E(r.name)}</b><span>${E(a.title||a.prompt||'Learning response')}</span><small>${E(r.group)} · ${date(a.at)}</small></span>${tag(a.correct===true?'Correct':reviewed(r,a)?'Reviewed':'To review',a.correct===true?'earned':'pending')}</a></li>`).join('')}</ul>`:empty('The next discovery is on its way.','Submitted answers appear here when students sync their work.')}<div class="td-desk-summary"><span><b data-td-review-count>${s.review}</b> responses to review</span><span><b data-td-earned>${s.achievements}</b> badges earned</span></div></section><section class="td-section"><header class="td-section-heading"><div><span class="td-kicker">PREPARE YOUR LESSONS</span><h2>Six systems. Endless curiosity.</h2><p>Preview the science, then choose what your classes can open.</p></div></header><div class="td-resource-grid">${L.worlds.map(w=>`<a href="${routeFor('','preview')}&system=${w.id}" data-resource-world="${w.id}"><img src="${image(w)}" alt="" width="100" height="67"><span>${w.name}<small>${w.titles.length} missions + final</small></span>${arrow}</a>`).join('')}</div><a class="td-button td-button-outline td-plan-link" href="${routeFor('','controls')}">${icon('connect')} Manage mission access ${arrow}</a></section></div>`;
  }
  function overview(){return `<div class="td-dashboard-toolbar"><p><span class="td-save-dot" aria-hidden="true"></span> ${E(schoolClasses.join(' · ')||'No classes assigned yet')}</p>${classSelect('td-dashboard-class',dashboardClass)}</div><div data-dashboard-overview>${overviewBody()}</div>`;}
  function analyticsBody(){
    const records=selectedRows(dashboardClass),graded=records.flatMap(r=>r.model.graded),correct=graded.filter(a=>a.correct).length;
    return `<div class="td-analytics-callouts"><article><span class="td-kicker">RECORDED ACCURACY</span><strong>${graded.length?Math.round(correct/graded.length*100)+'%':'—'}</strong><p>${correct} / ${graded.length} latest graded task responses correct</p></article><article><span class="td-kicker">CLASS CURIOSITY</span><strong>${number(stats(records).xp)} <small>XP</small></strong><p>Earned through completed learning tasks</p></article><article><span class="td-kicker">MASTERY KEYS</span><strong>${records.reduce((n,r)=>n+r.model.keys,0)}</strong><p>System finals completed by these students</p></article></div><div class="td-desk-grid"><section class="td-section"><header class="td-section-heading"><div><span class="td-kicker">STRUCTURE / UNDERSTANDING</span><h2>Progress across the systems</h2><p>Average mission and final completion. Select a system for student detail.</p></div></header><div class="td-analysis-bars">${L.worlds.map(w=>{const percent=records.length?Math.round(records.reduce((n,r)=>n+r.model.worlds.find(s=>s.id===w.id).percent,0)/records.length):0;return `<button type="button" data-td-system="${w.id}"><img src="${image(w)}" alt=""><span>${w.name}${meter(percent,w.name+' average completion')}</span><b>${percent}%</b></button>`;}).join('')}</div></section><section class="td-section"><span class="td-kicker">CLASSROOM PULSE</span><h2>Every class, in view.</h2><div class="td-class-pulse">${classOptions().filter(c=>!dashboardClass||c===dashboardClass).map(c=>{const students=selectedRows(c),s=stats(students);return `<article><header><b>${E(c)}</b><span>${students.length} students</span></header>${meter(s.progress,c+' average progress')}<p><b>${s.progress}%</b> average progress · <b>${s.review}</b> to review</p></article>`;}).join('')||'<p>No classes assigned yet.</p>'}</div><p class="td-footnote">Written responses are reviewed separately. Empty records contribute 0% progress; accuracy uses recorded graded answers only.</p></section></div>`;
  }
  function analytics(){return `<div class="td-dashboard-toolbar"><p>Learning evidence from the latest synced records.</p>${classSelect('td-analytics-class',dashboardClass)}</div><div data-dashboard-analytics>${analyticsBody()}</div>`;}
  const score=r=>boardMetric==='badges'?r.model.earned.length:boardMetric==='missions'?r.model.missions:r.model.xp;
  const scoreLabel=n=>boardMetric==='badges'?(n===1?'badge':'badges'):boardMetric==='missions'?(n===1?'mission':'missions'):'XP';
  function rankings(){const records=selectedRows(boardClass).sort((a,b)=>score(b)-score(a)||a.name.localeCompare(b.name)||a.id.localeCompare(b.id));let previous=null,rank=0;return records.map((r,i)=>{const points=score(r);if(points!==previous)rank=i+1;previous=points;return {r,points,rank:points?rank:null};});}
  function boardBody(){
    const ranked=rankings(),records=ranked.map(x=>x.r),active=ranked.filter(x=>x.rank),s=stats(records),missions=records.reduce((n,r)=>n+r.model.missions,0),earned=L.snapshot().badges.filter(b=>records.some(r=>r.model.earned.some(a=>a.id===b.id)));
    return `<section class="td-league-stage" aria-label="Class achievements"><div class="td-league-intro"><span class="td-kicker">${E(boardClass||'YOUR ASSIGNED CLASSES')} / DISCOVERY LEAGUE</span><h2>Small discoveries.<br><em>Legendary curiosity.</em></h2><p>Cheer the learning behind the numbers. Every explorer has a place here.</p><div class="td-league-totals"><span><b>${number(s.xp)}</b> class XP</span><span><b>${missions}</b> missions</span><span><b>${s.achievements}</b> badges</span></div><button type="button" class="td-button td-button-light" data-board-celebrate ${s.xp||missions||s.achievements?'':'disabled'}>✦ Celebrate the class</button><p data-board-cheer role="status" aria-live="polite"></p></div><div class="td-league-mascot" aria-hidden="true">${window.InneruAccount.markup('pip','Pip')}<span class="td-orbit-star">✦</span><span class="td-mascot-note">Curiosity looks<br>good on you!</span></div><div class="td-confetti" aria-hidden="true"></div></section>
    <section class="td-section td-podium-section"><header class="td-section-heading"><div><span class="td-kicker">EXPLORERS IN THE SPOTLIGHT</span><h2>Look who’s making discoveries.</h2><p>Ranked by earned ${scoreLabel()}. Equal scores share a rank; tied names appear alphabetically.</p></div></header>${active.length?`<ol class="td-podium">${active.slice(0,3).map(({r,points,rank},i)=>`<li class="td-podium-${i}" data-board-rank="${rank}"><button type="button" data-board-student="${E(r.id)}" aria-label="See ${E(r.name)}’s achievements"><span class="td-medal" aria-hidden="true">${rank===1?'♛':'✦'}</span>${portrait(r)}<strong>${E(r.name)}</strong><small>${E(r.group)}</small><b>${number(points)} <span>${scoreLabel(points)}</span></b><span class="td-podium-place">Rank ${rank}</span></button></li>`).join('')}</ol>`:empty('Ready, set… discover!','The spotlight opens when students earn their first '+scoreLabel()+'. Everyone starts with curiosity.')}</section>
    <section class="td-section"><header class="td-section-heading"><div><span class="td-kicker">THE WHOLE CREW</span><h2>Every explorer counts.</h2></div><span class="td-tag" data-board-count>${records.length} students</span></header>${ranked.length?`<ol class="td-league-roster">${ranked.map(({r,points,rank})=>`<li data-board-row="${E(r.id)}"><span class="td-league-rank">${rank?'#'+rank:'—'}</span><button type="button" class="td-league-person" data-board-student="${E(r.id)}">${portrait(r)}<span><b>${E(r.name)}</b><small>${E(r.group)} · ${rank?'Keep discovering!':'Ready to begin'}</small></span></button><dl><div><dt>XP</dt><dd>${number(r.model.xp)}</dd></div><div><dt>Missions</dt><dd>${r.model.missions}</dd></div><div><dt>Badges</dt><dd>${r.model.earned.length}</dd></div></dl><a class="td-open-link" href="${routeFor(r.id)}" aria-label="Open ${E(r.name)}’s learning record">${arrow}</a></li>`).join('')}</ol>`:empty('Your crew is on its way.','Students appear here after choosing one of your assigned classes.')}<p class="td-footnote">Only your assigned students are shown. Rankings use saved learning records and do not award extra points.</p></section>
    <section class="td-section"><header class="td-section-heading"><div><span class="td-kicker">THE CLASS TROPHY SHELF</span><h2>Badges with a story.</h2><p>Select a badge to see what earned it and who achieved it.</p></div></header>${earned.length?`<div class="td-badge-grid">${earned.map(b=>badge(b,null,records)).join('')}</div>`:empty('The trophy shelf is waiting.','Earned mission badges and mastery achievements appear automatically as students complete their tasks.')}</section>`;
  }
  function board(){return `<div class="td-league-controls"><div class="td-score-switch" role="group" aria-label="Rank students by">${[['xp','✦ Points'],['missions','⚑ Missions'],['badges','◇ Badges']].map(([key,label])=>`<button type="button" data-board-metric="${key}" aria-pressed="${boardMetric===key}">${label}</button>`).join('')}</div>${classSelect('td-board-class',boardClass)}</div><div data-board-content>${boardBody()}</div>`;}
  const viewTitles={overview:['Teacher Dashboard','Your students, recent submissions and learning resources at a glance.'],students:['Students','Follow the learning story behind every name in your classes.'],answers:['Feedback','Read submitted answers and guide each learner’s next discovery.'],controls:['Missions','Control access to the existing systems and missions for each assigned class.'],analytics:['Analytics','See learning patterns across your assigned classes.'],preview:['Mission previews','Explore every lesson as a teacher, including missions locked for students.'],board:['The Discovery League','Big curiosity. Small victories. Every discovery counts.']};
  function heading(view){const [title,description]=viewTitles[view]||viewTitles.overview;return `<header class="td-view-heading"><div><span class="td-kicker">${view==='board'?'YOUR CLASSROOM / CELEBRATE THE JOURNEY':'YOUR TEACHING WORKSPACE'}</span><h1>${title}</h1><p>${description}</p></div>${!['preview','board'].includes(view)?`<a class="td-text-link" href="${routeFor('','board')}">Open the Discovery League ${arrow}</a>`:''}</header>`;}
  function previewLibrary(){return `<section class="td-preview-library" aria-label="Teacher mission library">${L.worlds.map((w,i)=>`<article class="td-section"><header class="td-section-heading"><div><span class="td-kicker">SYSTEM ${String(i+1).padStart(2,'0')} / ${w.tag}</span><h2>${w.name} System</h2></div><img src="${image(w)}" width="100" height="67" alt=""></header><ol class="td-preview-list">${[...w.titles,w.final].map((title,j)=>`<li><span>${j===w.titles.length?'FINAL':String(j+1).padStart(2,'0')}</span><b>${E(title)}</b><a class="td-text-link" href="${(j===w.titles.length?L.finalRoute(w):L.missionRoute(w,j+1))+'?preview=1'}">Preview ${arrow}</a></li>`).join('')}</ol></article>`).join('')}</section>`;}
  function controlPanel(){
    if(controlError)return `<section class="td-section"><h2>Mission controls are unavailable.</h2><p role="alert">${E(controlError)}</p><button type="button" class="td-button" data-td-refresh>Try again</button></section>`;
    if(!controls?.classes.length)return empty('No school classes are assigned to this account.','Only your assigned classes can be managed here.');
    if(!controls.classes.some(c=>c.code===controlClass))controlClass=controls.classes[0].code;
    const classroom=controls.classes.find(c=>c.code===controlClass);
    return `<section class="td-section td-control-intro"><label for="td-control-class">Manage class<select id="td-control-class">${controls.classes.map(c=>`<option value="${E(c.code)}" ${c.code===controlClass?'selected':''}>${E(c.code)}</option>`).join('')}</select></label><p>Settings apply only to the selected class. Students also complete each mission before the next one opens. Existing progress is kept.</p><p class="td-control-status" role="status" data-control-status>Settings saved to your school account.</p></section><div class="td-control-systems">${classroom.systems.map((w,i)=>`<section class="td-section td-control-system" data-control-system="${w.id}"><header class="td-section-heading"><div><span class="td-kicker">SYSTEM ${String(i+1).padStart(2,'0')} / ${E(classroom.code)}</span><h2>${E(w.name)} System</h2><p data-system-status>${w.unlocked?'System unlocked':'System locked for this class'}</p></div><button type="button" class="td-button ${w.unlocked?'td-button-outline':''}" data-control-number="0" data-control-system-id="${w.id}" data-control-open="${!w.unlocked}" aria-label="${w.unlocked?'Lock':'Unlock'} ${E(w.name)} System for ${E(classroom.code)}">${w.unlocked?'Lock system':'Unlock system'}</button></header><ol class="td-control-list">${w.missions.map(m=>`<li><div><span class="td-kicker">${m.isFinal?'FINAL CHALLENGE':'MISSION '+String(m.number).padStart(2,'0')}</span><b>${E(m.title)}</b><small>${!w.unlocked?'System locked':m.unlocked?'Teacher unlocked · sequence applies':'Teacher locked'}</small></div><button type="button" class="td-button td-button-outline" data-control-number="${m.number}" data-control-system-id="${w.id}" data-control-open="${!m.unlocked}" aria-label="${m.unlocked?'Lock':'Unlock'} ${E(m.title)} for ${E(classroom.code)}">${m.unlocked?'Lock':'Unlock'}</button></li>`).join('')}</ol></section>`).join('')}</div>`;
  }
  function dialogMarkup(){return '<dialog class="td-dialog" aria-labelledby="td-dialog-title"><button type="button" class="td-dialog-close" data-td-close aria-label="Close details">Close ×</button><div data-td-dialog-body></div></dialog>';}
  function openDialog(html,opener){const dialog=document.querySelector('.td-dialog');dialog.querySelector('[data-td-dialog-body]').innerHTML=html;if(!dialog.open){dialog.returnFocus=opener;dialog.showModal();}else dialog.querySelector('[data-td-close]').focus();}
  function confirmAction(title,message,action,opener){openDialog(`<span class="td-kicker">CLASSROOM RECORDS</span><h2 id="td-dialog-title">${E(title)}</h2><p>${E(message)}</p><div class="td-actions"><button type="button" class="td-button" data-td-confirm>Confirm</button><button type="button" class="td-button td-button-outline" data-td-close>Keep things as they are</button></div>`,opener);document.querySelector('[data-td-confirm]').onclick=async()=>{document.querySelector('.td-dialog').close();await run(action);};}
  function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function csv(lines){return lines.map(line=>line.map(v=>{let s=String(v??'');if(/^[\s]*[=+@\-]/.test(s)||/^[\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}).join(',')).join('\r\n');}
  async function run(work){try{await work();}catch(error){notice={text:error.message||'This action could not be completed. Please try again.',error:true};const host=document.querySelector('[data-td-alerts]');if(host){host.innerHTML=alerts();host.querySelector('[role=alert]')?.scrollIntoView({block:'nearest'});}}}
  async function collect(payload){const select=document.querySelector('#td-import-target'),value=select?.value;const result=await T.upsert(payload,{targetId:value&&value!=='new'?value:undefined,separate:value==='new'});if(result.conflict){document.getElementById('t-import-out').innerHTML=`<p class="td-data-note">This older code has no learner ID. Choose which record to update, or add a different student with the same name.</p><label for="td-import-target">Student record<select id="td-import-target"><option value="">Choose a record</option>${result.conflict.map(r=>`<option value="${E(r.id)}">Update ${E(r.name)} · ${E(r.group||'no group')}</option>`).join('')}<option value="new">Add as a separate student</option></select></label>`;return;}notice={text:result.stale?'A newer snapshot is already saved. The older import was not applied.':(result.updated?'Updated ':'Added ')+result.record.name+'’s learning record.'};await render({preserve:true});}
  function wire(student){
    const root=document.querySelector('.td-page'),dialog=root.querySelector('dialog');
    dialog.addEventListener('close',()=>dialog.returnFocus?.isConnected&&dialog.returnFocus.focus({preventScroll:true}));
    dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
    root.addEventListener('input',event=>{if(event.target.closest('[data-td-notes],[data-td-feedback]'))dirty=true;if(event.target.id==='td-student-search'){search=event.target.value;root.querySelector('[data-td-table]').innerHTML=table(roster());root.querySelector('[data-td-roster-count]').textContent=roster().length+' of '+rows.length+' students shown.';}});
    root.addEventListener('change',event=>{
      const id=event.target.id;
      if(id==='td-board-class'){boardClass=event.target.value;root.querySelector('[data-board-content]').innerHTML=boardBody();return;}
      if(id==='td-dashboard-class'||id==='td-analytics-class'){dashboardClass=event.target.value;const target=root.querySelector(id==='td-dashboard-class'?'[data-dashboard-overview]':'[data-dashboard-analytics]');target.innerHTML=id==='td-dashboard-class'?overviewBody():analyticsBody();return;}

      if(id==='td-control-class'){controlClass=event.target.value;run(()=>render({preserve:true}));return;}
      if(id==='td-group-filter')group=event.target.value;if(id==='td-status-filter')filter=event.target.value;if(id==='td-sort')sort=event.target.value;
      if(['td-group-filter','td-status-filter','td-sort'].includes(id)){root.querySelector('[data-td-table]').innerHTML=table(roster());root.querySelector('[data-td-roster-count]').textContent=roster().length+' of '+rows.length+' students shown.';}
      if(id==='td-answer-system')answerSystem=event.target.value;if(id==='td-answer-status')answerStatus=event.target.value;
      if(['td-answer-system','td-answer-status'].includes(id)){root.querySelector('[data-td-answer-list]').innerHTML=answerCards(student);root.querySelector('[data-td-answer-count]').textContent=answerRows(student).length+' responses shown';}
      if(id==='td-badge-system'){badgeSystem=event.target.value;run(()=>render({preserve:true}));}
      if(event.target.hasAttribute('data-td-backup-file'))run(async()=>{const file=event.target.files[0];if(!file)return;if(file.size>10*1024*1024)throw new Error('Choose a classroom backup smaller than 10 MB.');const result=await T.importBackup(JSON.parse(await file.text()));notice={text:result.saved+' classroom records imported; '+result.older+' older snapshots left unchanged.'};await render({preserve:true});});
    });
    root.addEventListener('submit',event=>{event.preventDefault();const form=event.target;
      if(form.hasAttribute('data-td-notes'))run(async()=>{await T.edit(form.dataset.studentId,{group:form.querySelector('input').value,notes:form.querySelector('textarea').value});dirty=false;notice={text:'Teaching notes and class group saved.'};await render({preserve:true});});
      if(form.hasAttribute('data-td-feedback'))run(async()=>{const button=form.querySelector('button');button.disabled=true;try{let row;if(schoolMode){await classroomApi('feedback',{studentId:form.dataset.studentId,responseId:form.dataset.responseId,note:form.querySelector('textarea').value,reviewed:form.querySelector('input').checked,submissionAt:form.dataset.responseAt});const fresh=await classroomApi('classroom');const remote=fresh.students.find(s=>s.id===form.dataset.studentId);if(!remote)throw new Error('This student is no longer assigned to you. Refresh the roster.');row=cloudRecord(remote);}else row=await T.edit(form.dataset.studentId,{response:{responseId:form.dataset.responseId,at:form.dataset.responseAt,note:form.querySelector('textarea').value,reviewed:form.querySelector('input').checked}});const i=rows.findIndex(r=>r.id===row.id);Object.assign(rows[i],row,{model:T.model(row)});dirty=false;form.querySelector('.td-form-status').textContent='Teacher feedback saved. Student points and answers are unchanged.';const reviewCount=stats(student?rows.filter(r=>r.id===student.id):rows).review;const count=root.querySelector('[data-td-review-count]');if(count)count.textContent=reviewCount;const answer=rows[i].model.responses.find(a=>a.id===form.dataset.responseId),done=reviewed(rows[i],answer);form.closest('.td-answer').querySelector('.td-answer-meta .td-tag').outerHTML=tag(done?'Reviewed':'Not reviewed',done?'earned':'quiet');form.closest('.td-feedback').querySelector('summary').textContent=form.querySelector('textarea').value?'Teacher feedback saved':'Add feedback or mark reviewed';const tab=root.querySelector('.td-tabs a[href*="view=answers"]');if(tab){tab.querySelector('b')?.remove();if(reviewCount)tab.insertAdjacentHTML('beforeend','<b>'+reviewCount+'</b>');}}finally{button.disabled=false;}});
    });
    root.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;
      if(b.hasAttribute('data-board-metric')){boardMetric=b.dataset.boardMetric;root.querySelectorAll('[data-board-metric]').forEach(button=>button.setAttribute('aria-pressed',String(button===b)));root.querySelector('[data-board-content]').innerHTML=boardBody();return;}
      if(b.hasAttribute('data-board-celebrate')){root.querySelector('[data-board-cheer]').textContent='A round of applause for every discovery. Keep going, explorers!';const confetti=root.querySelector('.td-confetti');if(!motionReduced()){confetti.innerHTML=Array.from({length:24},(_,i)=>`<i style="--i:${i};--x:${(i*37)%100}%;--turn:${i*47}deg"></i>`).join('');setTimeout(()=>{if(confetti.isConnected)confetti.replaceChildren();},1700);}return;}
      if(b.hasAttribute('data-board-student')){const r=rows.find(r=>r.id===b.dataset.boardStudent);if(!r)return;openDialog(`<span class="td-kicker">EXPLORER PASSPORT / ${E(r.group)}</span><h2 id="td-dialog-title">${E(r.name)}’s discoveries</h2><div class="td-passport-avatar">${portrait(r)}</div><p>${number(r.model.xp)} XP · ${r.model.missions} missions complete · ${r.model.earned.length} badges</p>${r.model.earned.length?`<div class="td-badge-grid">${r.model.earned.map(b=>badge(b,r)).join('')}</div>`:'<p>The first badge is still ahead. Keep exploring!</p>'}<a class="td-button" href="${routeFor(r.id)}">Open learning record ${arrow}</a>`,b);return;}
      if(b.hasAttribute('data-control-number')){const classCode=controlClass,classSelect=root.querySelector('#td-control-class');classSelect.disabled=true;const buttons=[...root.querySelectorAll('[data-control-number]')];buttons.forEach(button=>button.disabled=true);const status=root.querySelector('[data-control-status]');status.textContent='Saving class settings…';run(async()=>{try{controls=await classroomApi('set-mission-control',{classCode,system:b.dataset.controlSystemId,number:Number(b.dataset.controlNumber),unlocked:b.dataset.controlOpen==='true'});notice={text:'Mission access updated for '+classCode+'. Existing student progress is unchanged.'};await render({preserve:true});}catch(error){classSelect.disabled=false;buttons.forEach(button=>button.disabled=false);status.textContent=error.message;throw error;}});return;}
      if(b.hasAttribute('data-td-close')){dialog.close();return;}
      if(b.hasAttribute('data-td-refresh')){if(dirty){confirmAction('Refresh saved records?','Unsaved teacher notes in this view will be replaced by the saved record.',()=>render({preserve:true}),b);}else run(()=>render({preserve:true}));return;}
      if(b.hasAttribute('data-td-import')&&schoolMode){location.hash=routeFor('','students');return;}
      if(b.hasAttribute('data-td-import')){root.querySelector('#td-sharing').scrollIntoView({block:'start',behavior:document.body.classList.contains('motionoff')||matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});root.querySelector('#t-import').focus({preventScroll:true});return;}
      if(b.hasAttribute('data-td-system')){const w=L.worlds.find(w=>w.id===b.dataset.tdSystem);openDialog(`<span class="td-kicker">CLASS PROGRESS / ${E(w.tag)}</span><h2 id="td-dialog-title">${w.name} System</h2>${rows.length?`<ul class="td-dialog-students">${selectedRows(dashboardClass).map(r=>{const p=r.model.worlds.find(s=>s.id===w.id);return `<li><a href="${routeFor(r.id,'progress')}"><b>${E(r.name)}</b><span>${p.percent}% · ${p.key?'Key earned':'In progress'}</span></a></li>`;}).join('')}</ul>`:schoolMode?'<p>Students appear automatically when they choose your classes.</p>':'<p>Import student progress to see this learning area across your class.</p>'}`,b);return;}
      if(b.hasAttribute('data-td-badge')){const r=b.dataset.studentId?rows.find(r=>r.id===b.dataset.studentId):null,badge=(r?r.model.badges:L.snapshot().badges).find(a=>a.id===b.dataset.tdBadge),earned=(r?[r]:['board','achievements'].includes(locationState().view)?selectedRows(boardClass):rows).filter(s=>s.model.badges.find(a=>a.id===badge.id)?.earned);openDialog(`<span class="td-kicker">${E(labelSystem(badge.system))} / ACHIEVEMENT</span><h2 id="td-dialog-title">${E(badge.name)}</h2><p>${E(badge.requirement)}</p><h3>${r?'Learning record':'Students with confirmed completion'}</h3>${earned.length?`<ul class="td-dialog-students">${earned.map(s=>`<li><a href="${routeFor(s.id,'achievements')}"><b>${E(s.name)}</b><span>${s.model.book?.completed?.['badge:'+badge.id]?date(s.model.book.completed['badge:'+badge.id]):'Completion confirmed · date not shared'}</span></a></li>`).join('')}</ul>`:'<p>No saved record confirms this achievement yet.</p>'}`,b);return;}
      if(b.id==='t-code')run(async()=>{const code=T.encode(state);root.querySelector('#t-code-out').innerHTML=`<label for="t-code-text">Student progress code</label><textarea id="t-code-text" class="input" rows="3" readonly>${E(code)}</textarea><button type="button" class="td-text-link" id="t-copy">Copy progress code</button>`;});
      if(b.id==='t-copy')run(async()=>{const field=root.querySelector('#t-code-text');try{await navigator.clipboard.writeText(field.value);b.textContent='Copied';}catch{field.select();b.textContent='Select and copy this code';}});
      if(b.id==='t-save')run(()=>collect(T.current()));
      if(b.id==='t-load'&&window.InneruAccount?.currentUser){toast('Sign out before replacing this device with an imported learner. Your account record has not changed.');return;}
      if(b.id==='t-add'||b.id==='t-load')run(async()=>{const result=T.decode(root.querySelector('#t-import').value);if(result.error){root.querySelector('#t-import-out').textContent=result.error;return;}if(b.id==='t-add'){const select=root.querySelector('#td-import-target');if(select&&!select.value){select.focus();return;}await collect(result.payload);}else{T.restore(result.payload);notice={text:'Learner restored on this device. The teacher register is unchanged. Undo is available for 10 minutes.'};await render({preserve:true});}});
      if(b.id==='t-reset'&&window.InneruAccount?.currentUser){toast('Sign out from your avatar menu to prepare this device without resetting account progress.');return;}
      if(b.id==='t-reset')confirmAction('Prepare this device for the next student?','The active learner will be cleared. Your teacher register stays intact, and this replacement can be undone for 10 minutes.',async()=>{T.resetCurrent();notice={text:'Ready for the next student. Undo is available for 10 minutes.'};await render({preserve:true});},b);
      if(b.id==='t-undo')run(async()=>{T.undo();notice={text:'The previous learner profile was restored.'};await render({preserve:true});});
      if(b.id==='t-clear')confirmAction('Clear the teacher register?','All imported student snapshots and teacher feedback in this browser will be removed. Active learner progress is untouched. Export a backup first if you want to keep these records.',async()=>{await T.clear();notice={text:'Teacher register cleared. Active learner progress was not changed.'};await render({preserve:true});},b);
      if(b.hasAttribute('data-td-remove'))confirmAction('Remove this student from the register?','This removes the saved classroom snapshot and teacher feedback. The student’s own learning profile is untouched.',async()=>{await T.remove(b.dataset.tdRemove);notice={text:'Student removed from the teacher register.'};location.hash=routeFor('','students');},b);
      if(b.id==='t-print'||b.hasAttribute('data-td-print'))window.print();
      if(b.hasAttribute('data-td-backup'))run(async()=>download('inneru-classroom-backup.json',JSON.stringify(await T.exportBackup(),null,2),'application/json'));
      if(b.hasAttribute('data-td-export-csv'))download('inneru-student-register.csv',csv([['Student','Class group','XP','Completed missions','Mastery keys','Confirmed achievements','Progress percent','Work to review','Snapshot shared (UTC)','Imported (UTC)'],...roster().map(r=>[r.name,r.group,r.model.xp,r.model.missions,r.model.keys,r.model.earned.length,r.model.percent,r.model.needsReview,r.payload.at||'',r.importedAt])]),'text/csv;charset=utf-8');
      if(b.hasAttribute('data-td-export-answers'))download('inneru-student-responses.csv',csv([['Student','Class group','Learning area','Task','Question','Student answer','Expected response','Automatic result','Recorded attempts','Submitted (UTC)','Teacher feedback','Reviewed latest submission'],...answerRows(student).map(({student:r,answer:a})=>[r.name,r.group,labelSystem(a.system),a.title,a.prompt,a.answer,a.expected,a.correct===null?'Not automatically graded':a.correct?'Correct':'Incorrect',a.attempts,a.at,r.feedback?.[a.id]?.note||'',reviewed(r,a)?'Yes':'No'])]),'text/csv;charset=utf-8');
    });
  }
  async function render(options={}){
    if(window.InneruAccess&&!InneruAccess.check("teacher"))return;
    const currentToken=++token,scroll=window.scrollY;dirty=false;
    try{
      let saved;const classroomData=await classroomApi('classroom');if(currentToken!==token)return;schoolMode=true;schoolClasses=classroomData.classes.filter(c=>c.schoolClass).map(c=>c.name);saved=classroomData.students.map(cloudRecord);if(window.InneruAccess&&!InneruAccess.check("teacher"))return;if(currentToken!==token||location.hash.slice(1).split(/[/?]/)[0]!=='teacher')return;
      rows=saved.map(r=>({...r,model:T.model(r)}));const locationInfo=locationState(),student=rows.find(r=>r.id===locationInfo.id),view=locationInfo.id?locationInfo.view:({home:'overview',achievements:'board'}[locationInfo.view]||locationInfo.view);
      if(locationInfo.id&&!student){notice={text:'This student record is no longer in the register.',error:true};locationInfo.id=null;}
      if(!student&&view==='controls'){controlError='';try{controls=await classroomApi('mission-controls');}catch(error){controlError=error.message;}}
      if(currentToken!==token)return;
      let content=student?view==='progress'?progress(student):view==='answers'?answers(student):view==='achievements'?achievements(student):view==='notes'?notes(student):studentSummary(student):view==='students'?register():view==='answers'?answers():view==='board'?board():view==='analytics'?analytics():view==='controls'?controlPanel():view==='preview'?previewLibrary():overview();
      layout(`<section class="td-page" aria-label="Teacher dashboard" data-teacher-page="${student?'student-'+view:view}">${topline(student)}${!student&&!['preview','board'].includes(view)?navigation(null,view):''}${student?hero(student):heading(view)}${student?navigation(student.id,view):''}<div data-td-alerts>${alerts(student)}</div>${content}${schoolMode?'<p class="td-data-note">Your school classes are assigned automatically. Refresh records to see the latest synced student work.</p>':tools()}<p class="td-bottom-note">${schoolMode?'Student records come from your assigned classes and their latest synced work.':'Classroom data stays in this browser. Imported work is a student snapshot, not a live connection to another device.'} UAE time · Asia/Dubai.</p>${dialogMarkup()}</section>`,'teacher');
      document.title='InnerU · '+(student?'Student learning record':view==='preview'?'Mission Preview':view==='board'?'Discovery League':'Teacher Dashboard');const crumb=document.querySelector('.topbar .crumb');if(crumb)crumb.textContent='Grade 10 Science / '+(view==='preview'?'Mission Preview':view==='board'?'Achievements Board':'Teacher Dashboard');const profile=document.querySelector('.topbar .profile');if(profile)profile.innerHTML='<span class="td-workspace-tag">TEACHER WORKSPACE</span>';
      wire(student);const resource=new URLSearchParams(location.hash.split('?')[1]||'').get('system');if(view==='preview'&&resource){const index=L.worlds.findIndex(w=>w.id===resource);document.querySelectorAll('.td-preview-library>article')[index]?.scrollIntoView({block:'start'});}if(options.preserve)window.scrollTo(0,scroll);else if(!(view==='preview'&&resource))window.scrollTo(0,0);
    }catch(error){if(currentToken!==token)return;layout(`<section class="td-page"><h1>Teacher Dashboard</h1><p class="td-notice is-error" role="alert">${E(error.message)}</p><p>Existing learner progress has not been changed. Refresh this page to try opening your classroom again.</p></section>`,'teacher');}
  }
  document.addEventListener('inneru-classroom',event=>{if(event.detail?.remote){const note=document.querySelector('[data-td-update]');if(note)note.hidden=false;}});
  window.InneruTeacherDashboard={render};
  const previousRoute=InneruRouteModules.renderer;
const moduleRoute=function(){if(location.hash.slice(1).split(/[/?]/)[0]==='teacher'){render();return;}token++;previousRoute();};
  InneruRouteModules.registerRenderer(moduleRoute);

})();
